package com.guocheng.mediapocket;
import java.io.*;import java.net.*;import java.util.*;
public class SubtitleTransportTest {
 public static void main(String[]args)throws Exception{try(ServerSocket server=new ServerSocket(0,4,InetAddress.getByName("127.0.0.1"))){Thread t=new Thread(()->{try{for(int i=0;i<2;i++)try(Socket client=server.accept()){BufferedReader reader=new BufferedReader(new InputStreamReader(client.getInputStream(),"US-ASCII"));StringBuilder request=new StringBuilder();String line;while((line=reader.readLine())!=null&&!line.isEmpty())request.append(line.toLowerCase(Locale.ROOT)).append('\n');boolean good=request.toString().contains("get /good.srt ")&&request.toString().contains("referer: https://api.douban.com/");byte[] body=(good?"1\n00:00:01,000 --> 00:00:02,000\n中文字幕\n\n":"Blocked").getBytes("UTF-8");client.getOutputStream().write(("HTTP/1.1 "+(good?200:403)+" Fixture\r\nContent-Length: "+body.length+"\r\nConnection: close\r\n\r\n").getBytes("US-ASCII"));client.getOutputStream().write(body);}}catch(Exception e){throw new RuntimeException(e);}});t.start();String base="http://127.0.0.1:"+server.getLocalPort();boolean rejected=false;try{SubtitleHttp.download(base+"/bad.srt",null);}catch(IOException e){rejected=e.getMessage().equals("HTTP 403");}if(!rejected)throw new AssertionError("HTTP error must reject this subtitle");byte[] bytes=SubtitleHttp.download(base+"/good.srt@Referer=https://api.douban.com/",null);if(SubtitleParser.parse(SubtitleTextRules.decode(bytes)).size()!=1)throw new AssertionError("valid header-dependent subtitle must parse");t.join(2000);System.out.println("PASS: real subtitle HTTP 403 rejected; header-dependent next subtitle downloaded and parsed by original renderer parser.");}}
}
